use std::env;

#[derive(Debug, Clone)]
pub struct Args {
    pub path: String,
    pub model: Option<String>,
    pub model_name: Option<String>,
    pub list_models: bool,
    pub max_count: Option<usize>,
    pub format: String,
    pub style: String,
    pub reverse: bool,
    pub local: bool,
    pub no_color: bool,
    pub color: String,
    pub debug: bool,
    pub sparse: bool,
    pub svg: bool,
    pub wrap: String,
    pub skip_repo_owner_validation: bool,
    pub command: Option<String>,
}

impl Default for Args {
    fn default() -> Self {
        Args {
            path: ".".to_string(),
            model: None,
            model_name: None,
            list_models: false,
            max_count: None,
            format: "oneline".to_string(),
            style: "normal".to_string(),
            reverse: false,
            local: false,
            no_color: false,
            color: "auto".to_string(),
            debug: false,
            sparse: false,
            svg: false,
            wrap: "auto 0 8".to_string(),
            skip_repo_owner_validation: false,
            command: None,
        }
    }
}

pub fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();
    let mut result = Args::default();
    let mut i = 1;

    while i < args.len() {
        match args[i].as_str() {
            "-V" | "--version" => {
                println!("git-graph 0.7.0");
                std::process::exit(0);
            }
            "-h" | "--help" => {
                print_help();
                std::process::exit(0);
            }
            "-p" | "--path" => {
                if i + 1 < args.len() {
                    result.path = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-m" | "--model" => {
                if i + 1 < args.len() {
                    result.model = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-n" | "--max-count" => {
                if i + 1 < args.len() {
                    if let Ok(n) = args[i + 1].parse() {
                        result.max_count = Some(n);
                    }
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-f" | "--format" => {
                if i + 1 < args.len() {
                    result.format = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-s" | "--style" => {
                if i + 1 < args.len() {
                    result.style = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-r" | "--reverse" => {
                result.reverse = true;
                i += 1;
            }
            "-l" | "--local" => {
                result.local = true;
                i += 1;
            }
            "--no-color" => {
                result.no_color = true;
                i += 1;
            }
            "--color" => {
                if i + 1 < args.len() {
                    result.color = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-d" | "--debug" => {
                result.debug = true;
                i += 1;
            }
            "-S" | "--sparse" => {
                result.sparse = true;
                i += 1;
            }
            "--svg" => {
                result.svg = true;
                i += 1;
            }
            "-w" | "--wrap" => {
                if i + 1 < args.len() {
                    result.wrap = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--skip-repo-owner-validation" => {
                result.skip_repo_owner_validation = true;
                i += 1;
            }
            "model" => {
                result.command = Some("model".to_string());
                i += 1;

                // Parse model subcommand args
                while i < args.len() {
                    match args[i].as_str() {
                        "-l" | "--list" => {
                            result.list_models = true;
                            i += 1;
                        }
                        _ => {
                            result.model_name = Some(args[i].clone());
                            i += 1;
                        }
                    }
                }
            }
            "help" => {
                result.command = Some("help".to_string());
                i += 1;
            }
            _ => {
                i += 1;
            }
        }
    }

    result
}

fn print_help() {
    println!("Structured Git graphs for your branching model.
    https://github.com/mlange-42/git-graph

EXAMPES:
