pub fn format_commit(commit: &Commit, format: &str) -> String {
    match format {
        "oneline" | "o" => {
            format!("{} {}{}", 
                commit.short_hash,
                if commit.refs.is_empty() { 
                    String::new() 
                } else { 
                    format!("({}) ", commit.refs) 
                },
                commit.subject
            )
        }
        "short" | "s" => {
            format_short(commit)
        }
        "medium" | "m" => {
            format_medium(commit)
        }
        "full" | "f" => {
            format_full(commit)
        }
        _ => {
            // Custom format
            format_custom(commit, format)
        }
    }
}

fn format_short(commit: &Commit) -> String {
    let mut result = format!("commit {}", commit.hash);

    if !commit.refs.is_empty() {
        result.push_str(&format!(" ({})", commit.refs));
    }

    result.push('\n');
    result.push_str(&format!("Author: {} {}", commit.author_name, commit.author_email));
    result.push('\n');
    result.push('\n');
