                            result.push_str(&commit.body);
                        }
                    }
                    'a' => {
                        chars.next();
                        if let Some(&modifier) = chars.peek() {
                            match modifier {
                                'n' => {
                                    chars.next();
                                    result.push_str(&commit.author_name);
