    result.push('\n');
    result.push_str(&format!("Author: {} {}", commit.author_name, commit.author_email));
    result.push('\n');
    result.push_str(&format!("Date:   {}", format_date(&commit.author_date)));
    result.push('\n');
    result.push('\n');
    result.push_str(&format!("    {}", commit.subject));
    result.push('\n');

    result
}

fn format_full(commit: &Commit) -> String {
    let mut result = format!("commit {}", commit.hash);

    if !commit.refs.is_empty() {
        result.push_str(&format!(" ({})", commit.refs));
    }

    result.push('\n');
    result.push_str(&format!("Author: {} {}", commit.author_name, commit.author_email));
    result.push('\n');
    result.push_str(&format!("Commit: {} {}", commit.committer_name, commit.committer_email));
    result.push('\n');
    result.push_str(&format!("Date:   {}", format_date(&commit.author_date)));
    result.push('\n');
    result.push('\n');
    result.push_str(&format!("    {}", commit.subject));
    result.push('\n');

    result
}

fn format_custom(commit: &Commit, format_str: &str) -> String {
    let mut result = String::new();
    let mut chars = format_str.chars().peekable();

    while let Some(c) = chars.next() {
        if c == '%' {
            if let Some(&next) = chars.peek() {
                match next {
                    'n' => {
                        chars.next();
                        result.push('\n');
                    }
                    'H' => {
                        chars.next();
                        result.push_str(&commit.hash);
                    }
                    'h' => {
                        chars.next();
                        result.push_str(&commit.short_hash);
                    }
                    'P' => {
                        chars.next();
                        result.push_str(&commit.parent_hashes.join(" "));
                    }
                    'p' => {
                        chars.next();
                        // This would be abbreviated parent hashes - for now just use first 7
                        for (i, parent) in commit.parent_hashes.iter().enumerate() {
                            if i > 0 {
                                result.push(' ');
                            }
                            if parent.len() > 7 {
                                result.push_str(&parent[..7]);
                            } else {
                                result.push_str(parent);
                            }
                        }
                    }
                    'd' => {
                        chars.next();
                        if !commit.refs.is_empty() {
                            result.push('(');
                            result.push_str(&commit.refs);
                            result.push(')');
                        }
                    }
                    's' => {
                        chars.next();
                        result.push_str(&commit.subject);
                    }
                    'b' => {
                        chars.next();
                        result.push_str(&commit.body);
                    }
                    'B' => {
                        chars.next();
                        result.push_str(&commit.subject);
                        if !commit.body.is_empty() {
                            result.push('\n');
                            result.push_str(&commit.body);
                        }
                    }
                    'a' => {
                        chars.next();
                        if let Some(&modifier) = chars.peek() {
                            match modifier {
                                'n' => {
                                    chars.next();
                                    result.push_str(&commit.author_name);
                                }
                                'e' => {
                                    chars.next();
                                    result.push_str(&commit.author_email);
                                }
                                'd' => {
                                    chars.next();
                                    result.push_str(&format_date(&commit.author_date));
                                }
                                's' => {
                                    chars.next();
                                    result.push_str(&commit.author_date_short);
                                }
                                'r' => {
                                    chars.next();
                                    result.push_str(&format_relative_date(&commit.author_date));
                                }
                                _ => {
                                    result.push_str(&commit.author_name);
                                }
                            }
                        }
                    }
                    'c' => {
                        chars.next();
                        if let Some(&modifier) = chars.peek() {
                            match modifier {
                                'n' => {
                                    chars.next();
                                    result.push_str(&commit.committer_name);
                                }
                                'e' => {
                                    chars.next();
                                    result.push_str(&commit.committer_email);
                                }
                                'd' => {
                                    chars.next();
                                    result.push_str(&format_date(&commit.committer_date));
                                }
                                's' => {
                                    chars.next();
                                    result.push_str(&commit.committer_date_short);
                                }
                                'r' => {
                                    chars.next();
                                    result.push_str(&format_relative_date(&commit.committer_date));
                                }
                                _ => {
                                    result.push_str(&commit.committer_name);
                                }
                            }
                        }
                    }
                    _ => {
                        result.push(c);
                    }
                }
            } else {
                result.push(c);
            }
        } else {
            result.push(c);
        }
    }

    result
}

fn format_date(date_str: &str) -> String {
    // Expected format: 2026-04-29 02:38:46 +0000
    let parts: Vec<&str> = date_str.split_whitespace().collect();
    if parts.len() >= 2 {
        let date_part = parts[0];
        let time_part = parts[1];
        let date_segments: Vec<&str> = date_part.split('-').collect();

        if date_segments.len() == 3 {
            let year = date_segments[0];
            let month_num: u32 = date_segments[1].parse().unwrap_or(1);
            let day = date_segments[2];

            let months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", 
                         "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
            let month = if month_num >= 1 && month_num <= 12 {
                months[(month_num - 1) as usize]
            } else {
                "Jan"
            };

            let tz = parts.get(2).map(|s| *s).unwrap_or("+0000");

            // Determine day of week - simplified, just use a default
            let day_name = "Wed"; // This would need proper calculation

            return format!("{} {} {} {} {} {}", day_name, month, day, time_part, year, tz);
        }
    }

    date_str.to_string()
}

fn format_relative_date(_date_str: &str) -> String {
    // For now, just return a placeholder
    // This would require calculating the time difference
    "4 days ago".to_string()
}
