                result.local = true;
                i += 1;
            }
            "--no-color" => {
                result.no_color = true;
                i += 1;
            }
            "--color" => {
                if i + 1 < args.len() {
                    result.color = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-d" | "--debug" => {
                result.debug = true;
                i += 1;
            }
            "-S" | "--sparse" => {
                result.sparse = true;
                i += 1;
            }
            "--svg" => {
                result.svg = true;
                i += 1;
            }
            "-w" | "--wrap" => {
                if i + 1 < args.len() {
                    result.wrap = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--skip-repo-owner-validation" => {
                result.skip_repo_owner_validation = true;
                i += 1;
            }
            "model" => {
                result.command = Some("model".to_string());
                i += 1;

                // Parse model subcommand args
                while i < args.len() {
                    match args[i].as_str() {
                        "-l" | "--list" => {
