use std::fs;
use std::io;
use std::path::PathBuf;
use std::process::Command;

#[derive(Debug, Clone)]
pub struct Commit {
    pub hash: String,
    pub short_hash: String,
    pub parent_hashes: Vec<String>,
    pub author_name: String,
    pub author_email: String,
    pub author_date: String,
    pub author_date_short: String,
    pub committer_name: String,
    pub committer_email: String,
    pub committer_date: String,
    pub committer_date_short: String,
    pub subject: String,
    pub body: String,
    pub refs: String,
}

pub struct Repository {
    path: PathBuf,
}

impl Repository {
    pub fn open(path: &str) -> io::Result<Self> {
        let repo_path = if path == "." {
            PathBuf::from(".")
        } else {
            PathBuf::from(path)
        };

        // Verify it's a git repository
        let git_dir = repo_path.join(".git");
        if !git_dir.exists() {
            return Err(io::Error::new(io::ErrorKind::NotFound, "Not a git repository"));
        }

        Ok(Repository { path: repo_path })
    }

    pub fn get_commits(&self, max_count: &Option<usize>) -> io::Result<Vec<Commit>> {
        let mut cmd = Command::new("git");
        cmd.current_dir(&self.path);
        cmd.arg("log");
        cmd.arg("--all");
        cmd.arg("--oneline");
        cmd.arg("--decorate");
        cmd.arg("--format=format:%H%n%h%n%P%n%p%n%an%n%ae%n%ad%n%as%n%cn%n%ce%n%cd%n%cs%n%s%n%b%n%d%n---");
        cmd.arg("--date=iso8601");

        if let Some(count) = max_count {
            cmd.arg(format!("-n{}", count));
        }

        let output = cmd.output()?;

        if !output.status.success() {
            return Err(io::Error::new(io::ErrorKind::Other, "git log failed"));
        }

        let stdout = String::from_utf8_lossy(&output.stdout);
        let commits = parse_commits(&stdout);

        Ok(commits)
    }

    pub fn set_model(&self, model: &str) -> io::Result<()> {
        let config_path = self.path.join(".git/config");
        let mut content = fs::read_to_string(&config_path)?;

        // Remove existing git-graph section if it exists
        if let Some(start) = content.find("[git-graph]") {
            if let Some(end) = content[start..].find('\n') {
                let section_end = start + end;
                if let Some(next_section) = content[section_end..].find('[') {
                    content.drain(start..section_end + next_section);
                } else {
                    content.truncate(start);
                }
            }
        }

        // Add new model setting
        if !content.ends_with('\n') {
            content.push('\n');
        }
        content.push_str("[git-graph]\n");
        content.push_str("\tmodel = ");
        content.push_str(model);
        content.push('\n');

        fs::write(&config_path, content)?;

        Ok(())
    }

    pub fn get_model(&self) -> io::Result<Option<String>> {
        let config_path = self.path.join(".git/config");
        let content = fs::read_to_string(&config_path)?;

        let mut in_section = false;
        for line in content.lines() {
            if line == "[git-graph]" {
                in_section = true;
                continue;
            }

            if line.starts_with('[') {
                in_section = false;
            }

            if in_section {
                if line.trim_start().starts_with("model") {
                    if let Some(eq_pos) = line.find('=') {
                        let value = line[eq_pos + 1..].trim();
                        return Ok(Some(value.to_string()));
                    }
                }
            }
        }

        Ok(None)
    }
}

fn parse_commits(output: &str) -> Vec<Commit> {
    let mut commits = Vec::new();
    let entries: Vec<&str> = output.split("---\n").collect();

    for entry in entries {
        let trimmed = entry.trim();
        if trimmed.is_empty() {
            continue;
        }

        let lines: Vec<&str> = trimmed.lines().collect();
        if lines.len() < 13 {
            continue;
        }

        let hash = lines[0].to_string();
        let short_hash = lines[1].to_string();

        let parent_hashes = if !lines[2].is_empty() {
            lines[2].split_whitespace().map(|s| s.to_string()).collect()
        } else {
            Vec::new()
        };

        let author_name = lines[4].to_string();
        let author_email = lines[5].to_string();
        let author_date = lines[6].to_string();
        let author_date_short = lines[7].to_string();
        let committer_name = lines[8].to_string();
        let committer_email = lines[9].to_string();
        let committer_date = lines[10].to_string();
        let committer_date_short = lines[11].to_string();
        let subject = lines[12].to_string();

        // Find body and refs
        let mut body = String::new();
        let mut refs = String::new();

        for i in 13..lines.len() {
            let line = lines[i];
            if line.starts_with('(') && line.ends_with(')') {
                refs = line.trim_start_matches('(').trim_end_matches(')').to_string();
            } else if !line.trim().is_empty() {
                if !body.is_empty() {
                    body.push('\n');
                }
                body.push_str(line);
            }
        }

        commits.push(Commit {
            hash,
            short_hash,
            parent_hashes,
            author_name,
            author_email,
            author_date,
            author_date_short,
            committer_name,
            committer_email,
            committer_date,
            committer_date_short,
            subject,
            body,
            refs,
        });
    }

    commits
}
