use crate::cli::Args;
use crate::git::Commit;
use crate::format::format_commit;

pub struct Graph {
    commits: Vec<Commit>,
    args: Args,
}

impl Graph {
    pub fn new(mut commits: Vec<Commit>, args: Args) -> Self {
        if args.reverse {
            commits.reverse();
        }

        Graph { commits, args }
    }

    pub fn display(&self) {
        for (i, commit) in self.commits.iter().enumerate() {
            let is_last = i == self.commits.len() - 1;

            // Print the commit node
            let node_char = match self.args.style.as_str() {
                "ascii" => "*",
                _ => "●",
            };

            let line_char = match self.args.style.as_str() {
                "ascii" => "|",
                _ => "│",
            };

            // For oneline format, just print space before the node
            print!(" ");

            print!("{}", node_char);
            print!("  ");

            let formatted = format_commit(commit, &self.args.format);

            // For formats other than oneline, handle multi-line output with graph lines
            let lines: Vec<&str> = formatted.lines().collect();

            if lines.is_empty() {
                println!();
                continue;
            }

            println!("{}", lines[0]);

            // Print remaining lines with graph continuation
            for line in &lines[1..] {
                if is_last {
                    print!("    ");
                } else {
                    print!(" {} ", line_char);
                }
                println!("{}", line);
            }
        }
    }
}
