        }
        _ => {
            // Custom format
            format_custom(commit, format)
        }
    }
}

fn sort_refs(refs: &str) -> String {
    let mut parts: Vec<&str> = refs.split(", ").collect();
    // Separate HEAD from other refs
    let mut head = None;
    let mut other_refs = Vec::new();

    for part in parts {
        if part.starts_with("HEAD") {
            head = Some(part);
        } else {
