        }
        "full" | "f" => {
            format_full(commit)
        }
        _ => {
            // Custom format
            format_custom(commit, format)
        }
    }
}

fn sort_refs(refs: &str) -> String {
    let mut parts: Vec<&str> = refs.split(", ").collect();
    // Separate HEAD from other refs
    let mut head = None;
    let mut other_refs = Vec::new();

    for part in parts {
        if part.starts_with("HEAD") {
            head = Some(part);
        } else {
            other_refs.push(part);
        }
    }

    // Sort other refs (by putting persistent branches first, then feature branches)
    other_refs.sort_by(|a, b| {
        // Priority order: master/main -> branches starting with 'release' -> develop -> others
        let priority_a = ref_priority(a);
        let priority_b = ref_priority(b);

        if priority_a != priority_b {
            priority_a.cmp(&priority_b)
        } else {
            a.cmp(b)
        }
    });

    // Reconstruct refs string
    let mut result = String::new();
    if let Some(h) = head {
        result.push_str(h);
    }

    for (i, r) in other_refs.iter().enumerate() {
        if !result.is_empty() {
            result.push_str(", ");
        }
        result.push_str(r);
    }

    result
}

fn ref_priority(ref_name: &str) -> u32 {
    if ref_name.contains("master") || ref_name.contains("main") || ref_name.contains("trunk") {
        0
    } else if ref_name.contains("release") || ref_name.contains("hotfix") {
        1
    } else if ref_name.contains("develop") {
        2
    } else if ref_name.contains("feature") {
        3
    } else if ref_name.contains("tag") {
        4
    } else {
        5
    }
}

