fn main() -> io::Result<()> {
    let args = parse_args();

    match &args.command {
        Some(cmd) => {
            match cmd.as_str() {
                "model" => {
                    handle_model_command(&args)?;
                }
                "help" => {
                    print_help();
                }
                _ => eprintln!("Unknown command: {}", cmd),
            }
        }
        None => {
            // Main graph display
            display_graph(&args)?;
        }
    }

    Ok(())
}

fn handle_model_command(args: &cli::Args) -> io::Result<()> {
    let repo = Repository::open(&args.path)?;

    // Check if there's a model argument
    if let Some(model) = &args.model_name {
        repo.set_model(model)?;
        println!("Branching model set to '{}'", model);
    } else if args.list_models {
        println!("git-flow");
        println!("simple");
        println!("none");
    } else {
        // Show current model - NO NEWLINE
        match repo.get_model()? {
            Some(m) => print!("{}", m),
            None => print!("No branching model set"),
        }
    }

    Ok(())
}

fn display_graph(args: &cli::Args) -> io::Result<()> {
    let repo = Repository::open(&args.path)?;
    let commits = repo.get_commits(&args.max_count)?;

    let graph = graph::Graph::new(commits, args.clone());
    graph.display();

    Ok(())
}

